Q: How to set up an update route in Express A: <p>You request URL is <code>/posts/update/:id</code> but I don't see that path in any express router.
You are missin /posts in your router</p>

<pre class="lang-js prettyprint-override"><code>postRoutes.post('/update/:id', async(req, res)=&gt; {
    const collection = await loadPostsCollection();
    let id = req.params.id;
    let result = await collection.findOne(req.params.id)
    if (!result) {
      res.status(404).send("data is not found");
    }
    else {
        result.title = req.body.title;
        result.body = req.body.body;
        result.updateOne();
    }
});
</code></pre>
